"use strict";class InputValidator{constructor(){this.maxMessageLength=1e4;this.maxThreadNameLength=255;this.maxNicknameLength=50}isValidThreadID(threadID){if(!threadID)return false;const id=String(threadID).trim();return/^\d{1,20}$/.test(id)}isValidUserID(userID){return this.isValidThreadID(userID)}isValidMessage(message){if(typeof message==="string"){return message.length>0&&message.length<=this.maxMessageLength}if(typeof message==="object"&&message!==null){return message.body||message.sticker||message.attachment||message.emoji}return false}sanitizeMessage(message){if(typeof message!=="string")return message;return message.replace(/[\x00-\x1F\x7F]/g,"").trim()}sanitizeThreadName(name){if(typeof name!=="string")return null;const sanitized=name.trim();return sanitized.length>0&&sanitized.length<=this.maxThreadNameLength?sanitized:null}sanitizeNickname(nickname){if(typeof nickname!=="string")return null;const sanitized=nickname.trim();return sanitized.length>0&&sanitized.length<=this.maxNicknameLength?sanitized:null}validateIDArray(ids,validator=this.isValidThreadID.bind(this)){if(!Array.isArray(ids))return false;return ids.length>0&&ids.length<=100&&ids.every(validator)}isValidEmail(email){const emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;return emailRegex.test(email)}isValidUrl(url){try{new URL(url);return true}catch{return false}}isValidFilePath(path){if(typeof path!=="string")return false;return path.length>0&&path.length<=255&&!path.includes("\0")}isValidEmoji(emoji){if(typeof emoji!=="string")return false;return/\p{Emoji}/u.test(emoji)||emoji.length===1}}const globalValidator=new InputValidator;module.exports={InputValidator:InputValidator,globalValidator:globalValidator,validateThreadID:id=>globalValidator.isValidThreadID(id),validateUserID:id=>globalValidator.isValidUserID(id),validateMessage:msg=>globalValidator.isValidMessage(msg),sanitizeMessage:msg=>globalValidator.sanitizeMessage(msg),sanitizeThreadName:name=>globalValidator.sanitizeThreadName(name),sanitizeNickname:nick=>globalValidator.sanitizeNickname(nick),validateIDArray:(ids,validator)=>globalValidator.validateIDArray(ids,validator),isValidEmail:email=>globalValidator.isValidEmail(email),isValidUrl:url=>globalValidator.isValidUrl(url),isValidFilePath:path=>globalValidator.isValidFilePath(path),isValidEmoji:emoji=>globalValidator.isValidEmoji(emoji)};
